99	  orgId: OrgId,
100	  comment: Comment,
101	): Promise<void> {
102	  await searchRepo.upsertSearchDocument(
103	    orgId,
104	    "comment",
105	    comment.id,
106	    comment.body,
107	    null,
108	  );
109	}
