1	"use server";
2	
3	/**
4	 * Board drag-and-drop target; reconciles the optimistic update.
5	 *
6	 * Owner D. The client has already moved the card via `useOptimisticIssues`, so
7	 * the only thing that matters here is returning the authoritative row — the
8	 * hook reconciles against it and snaps the card back if the move was refused.
9	 * Dragging is only reachable when `kanban_board` is on, and the flag is
10	 * re-checked server-side because the client copy is only a snapshot.
11	 *
12	 * Must call (do not reimplement): moveIssueSchema, can, isEnabled, getActor,
13	 * toActionResult
14	 */
15	
16	import {
17	  FeatureUnavailableError,
18	  ForbiddenActionError,
19	} from "@/actions/_lib/action-errors";
20	import { PENDING_PROJECT_ID } from "@/actions/_lib/permission-resources";
21	import { withAction } from "@/actions/_lib/with-action";
22	import { CACHE_PROFILES, issueTag, projectTag, revalidateTagged } from "@/lib/cache";
23	import { isEnabled } from "@/lib/feature-flags";
24	import { can } from "@/lib/permissions";
25	import { moveIssueSchema, type MoveIssueInput } from "@/schemas/issue";
26	import { buildFlagContext } from "@/server/services/feature-flag-service";
27	import { moveIssue } from "@/server/services/issue-service";
28	import { getOrganizationSummary } from "@/server/services/organization-service";
29	import type { ActionResult } from "@/types/api";
30	import type { Issue } from "@/types/issue";
31	
32	const run = withAction<typeof moveIssueSchema, Issue>(
33	  moveIssueSchema,
34	  async (raw, actor) => {
35	    const input = raw as MoveIssueInput;
36	
37	    const allowed = can(actor, "issue:update", {
38	      kind: "issue",
39	      orgId: input.orgId,
40	      projectId: PENDING_PROJECT_ID,
41	      issueId: input.issueId,
42	      authorId: actor.userId,
43	      assigneeId: actor.userId,
44	    });
45	    if (!allowed) {
46	      throw new ForbiddenActionError("issue:update");
47	    }
48	
49	    const { organization } = await getOrganizationSummary(actor, input.orgId);
50	    if (!isEnabled("kanban_board", buildFlagContext(actor, organization))) {
51	      throw new FeatureUnavailableError("kanban_board");
52	    }
53	
54	    const issue = await moveIssue(actor, input);
55	    revalidateTagged(
56	      [issueTag(issue.id), projectTag(issue.projectId)],
57	      CACHE_PROFILES.seconds,
58	    );
59	    return issue;
60	  },
61	  { revalidate: ["board"], cacheProfile: "seconds" },
62	);
63	
64	export async function moveIssueAction(raw: unknown): Promise<ActionResult<Issue>> {
65	  return run(raw);
66	}
