/**
 * Next per-project issue number. Archived issues keep their number, so the
 * max is taken over every row rather than the live ones.
 */
export async function nextIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const row = getDb()
    .select({ value: sql<number | null>`max(${issues.number})` })
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
    )
    .get();
  return (row?.value ?? 0) + 1;
}

input.new_string:
/**
 * Next per-project issue number, claimed from the project's own counter
 * rather than derived from the rows currently in it — a number an issue once
 * carried stays retired even after that issue archives, moves away, or moves
 * away and back, because nothing ever lowers the counter.
 */
export async function nextIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const row = getDb()
    .update(projects)
    .set({ nextIssueNumber: sql`${projects.nextIssueNumber} + 1` })
    .where(and(orgPredicate(projects.orgId, orgId), eq(projects.id, projectId)))
    .returning({ value: projects.nextIssueNumber })
    .get();

  if (!row) throw new Error(`Project ${projectId} not found`);
  return row.value - 1;
}

