import { afterAll, beforeAll, describe, expect, it } from "vitest";

import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import { listActivity, registerActivityListeners } from "@/server/services/activity-service";
import * as issueService from "@/server/services/issue-service";
import { createTenant, issueInput, useTemporaryDatabase } from "./server/_support/fixtures";
import type { Tenant } from "./server/_support/fixtures";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
let tenant: Tenant;
let detach: Unsubscribe;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("movetmp", "growth");
  detach = registerActivityListeners();
});

afterAll(() => {
  detach();
  cleanup();
});

describe("tmp verify moveIssueToProject", () => {
  it("moves, renumbers, retires the old number, emits once, audits under target", async () => {
    const other = await projectRepo.insertProject({
      orgId: tenant.org.id,
      name: "Other",
      slug: "other",
      key: "OTH",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });

    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Move me" }),
    );
    expect(issue.number).toBe(1);

    const seen: unknown[] = [];
    const off = subscribe("issue.moved", (p) => seen.push(p));

    const moved = await issueService.moveIssueToProject(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      toProjectId: other.id,
    });

    expect(moved.projectId).toBe(other.id);
    expect(moved.number).toBe(1);
    expect(moved.title).toBe("Move me");
    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({
      issueId: issue.id,
      fromProjectId: tenant.project.id,
      toProjectId: other.id,
      fromNumber: 1,
      toNumber: 1,
    });
    off();

    // Same-project move is a no-op: no new event.
    const seen2: unknown[] = [];
    const off2 = subscribe("issue.moved", (p) => seen2.push(p));
    const again = await issueService.moveIssueToProject(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: moved.id,
      toProjectId: other.id,
    });
    expect(again).toEqual(moved);
    expect(seen2).toHaveLength(0);
    off2();

    // The old project's next number skips the retired number 1.
    const backfill = await issueService.createIssue(
